<script module>  export const manifiesto = {    id: 'inventario',    nombre: 'Inventario',    icono: 'package',    grupo: 'negocio',    orden: 4,    tablas: { ajustes: '++id, fecha, productoId' },  };</script><script>  import { onMount } from 'svelte';  import { listar } from '../../core/db.js';  import { bus } from '../../core/bus.js';  import { avisar } from '../../core/state.svelte.js';  import { n, m, fmt, fmtCant, fmtFH, stockVariante, valorLotesVariante, lotesDeVariante } from '../../core/util.js';  import { ConversionService } from '../../services/ConversionService.js';  import { InventarioService } from '../../services/InventarioService.js';  import { obtenerPeriodosCerrados } from '../../core/periodos.js';  import Icono from '../../core/Icono.svelte';  let productos = $state([]);  let variantes = $state([]);  let lotes = $state([]);  let ajustes = $state([]);  const expandido = $state({});  let procesando = $state(false);  let periodosCerrados = $state([]);  let form = $state({ productoId: '', varianteId: '', cantidad: '', motivo: '', costoSobrante: '' });  let busqProd = $state('');  let focusBusqProd = $state(false);  let busqProdDebounced = $state('');  $effect(() => { const t = setTimeout(() => (busqProdDebounced = busqProd), 200); return () => clearTimeout(t); });  const prodsActivos = $derived(productos.filter((p) => !p.archivado));  const prodsFiltrados = $derived((() => {    const q = busqProdDebounced.toLowerCase().trim();    if (!q) return prodsActivos.slice(0, 8);    return prodsActivos.filter((p) => p.nombre.toLowerCase().includes(q)).slice(0, 8);  })());  const valInv = $derived(lotes.filter((l) => n(l.cantidadInicial) - n(l.cantidadVendida) > 0).reduce((s, l) => s + (n(l.cantidadInicial) - n(l.cantidadVendida)) * n(l.costo), 0));  const unidadesTotal = $derived(lotes.filter((l) => n(l.cantidadInicial) - n(l.cantidadVendida) > 0).reduce((s, l) => s + (n(l.cantidadInicial) - n(l.cantidadVendida)), 0));  const lotesActivos = $derived(lotes.filter((l) => n(l.cantidadInicial) - n(l.cantidadVendida) > 0).length);  const ajustesRecientes = $derived(ajustes.slice().sort((a, b) => new Date(b.fecha) - new Date(a.fecha)).slice(0, 20));  async function recargar() {    [productos, variantes, lotes, ajustes] = await Promise.all([listar('productos'), listar('productoVariantes'), listar('lotes'), listar('ajustes')]);    periodosCerrados = await obtenerPeriodosCerrados();  }  function esCerrado(fechaIso) {    const f = new Date(fechaIso);    return periodosCerrados.some((p) => new Date(p.inicio) <= f && f <= new Date(p.fin));  }  onMount(() => { recargar(); const off = bus.on('recargar', recargar); return () => off(); });  function variantesDeProducto(pid) { return variantes.filter((v) => v.productoId === pid && !v.archivado); }  async function registrarAjuste() {    if (procesando) return;    const cant = n(form.cantidad);    if (!form.varianteId) return avisar('Selecciona variante', 'bad');    if (cant === 0) return avisar('Cantidad no puede ser 0', 'bad');    if (!form.motivo) return avisar('Selecciona motivo', 'bad');    const v = variantes.find((x) => x.id === form.varianteId);    const prod = productos.find((p) => p.id === v.productoId);    if (cant < 0 && Math.abs(cant) > stockVariante(lotes, form.varianteId))      return avisar('Solo hay ' + stockVariante(lotes, form.varianteId) + ' ' + (v.unidad || ''), 'bad');    procesando = true;    try {      if (cant < 0) {        const { costoPerdida } = await InventarioService.ajustarNegativo({          productoId: v.productoId, varianteId: v.id, productoNombre: v.nombre,          cantidad: Math.abs(cant), motivo: form.motivo, lotes,        });        await recargar(); bus.emit('recargar');        avisar('Merma registrada · perdida ' + fmt(costoPerdida));      } else {        const cs = n(form.costoSobrante);        if (cs < 0) return avisar('Costo invalido', 'bad');        await InventarioService.ajustarPositivo({          productoId: v.productoId, varianteId: v.id, productoNombre: v.nombre,          productoUnidad: v.unidad, cantidad: cant, motivo: form.motivo, costo: cs,        });        await recargar(); bus.emit('recargar');        avisar('Sobrante registrado');      }      form = { productoId: '', varianteId: '', cantidad: '', motivo: '', costoSobrante: '' };    } catch (e) { avisar(e.message, 'bad'); }    finally { procesando = false; }  }</script><div class='modulo'>  <!-- Valor inventario --><div class='bg-gradient-to-br from-success to-[#15803d] text-white rounded-[var(--radius-lg)] p-5 text-center mb-3 shadow-[var(--color-shadow)] relative overflow-hidden'>    <div class='absolute top-0 right-0 w-32 h-32 bg-white/5 rounded-full -translate-y-1/2 translate-x-1/2'></div>    <div class='absolute bottom-0 left-0 w-24 h-24 bg-white/5 rounded-full translate-y-1/2 -translate-x-1/2'></div>    <div class='relative'>      <div class='flex items-center justify-center gap-1.5 text-xs opacity-90 mb-1'>        <Icono nombre='package' size={14} color='#fff' />        Valor del Inventario      </div>      <div class='text-3xl font-extrabold my-0.5'>{fmt(valInv)}</div>      <div class='text-xs opacity-85'>{fmtCant(unidadesTotal, true)} unidades · {lotesActivos} lotes</div>    </div>  </div>  <!-- Ajuste --><div class='bg-card rounded-[var(--radius-lg)] p-4 shadow-[var(--color-shadow)] mb-3'>    <div class='flex items-center gap-2 font-extrabold text-warning mb-3'>      <Icono nombre='alert' size={18} />      Merma / Ajuste    </div>    <div class='relative mb-2'>      <Icono nombre='search' size={16} class='absolute left-3 top-1/2 -translate-y-1/2 text-muted' />      <input class='w-full pl-9 pr-3.5 py-2.5 border border-border rounded-[var(--radius-md)] bg-card text-text text-sm outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)]' type='text' placeholder='Buscar producto...' bind:value={busqProd} onfocus={() => (focusBusqProd = true)} onblur={() => setTimeout(() => (focusBusqProd = false), 200)} />      {#if focusBusqProd && prodsFiltrados.length > 0}        <div class='absolute left-0 right-0 top-full mt-1 border border-border rounded-[var(--radius-md)] bg-card max-h-48 overflow-y-auto shadow-[var(--color-shadow)] z-20'>          {#each prodsFiltrados as p}            <button class='w-full text-left px-3.5 py-2.5 text-sm border-b border-border/50 last:border-none hover:bg-background transition-colors flex items-center justify-between gap-2' onclick={() => { form.productoId = p.id; busqProd = p.nombre; focusBusqProd = false; }}>              <span class='font-medium truncate'>{p.nombre}</span>            </button>          {/each}        </div>      {/if}    </div>    {#if form.productoId}      {@const selProd = productos.find((p) => p.id === form.productoId)}      {#if selProd}        <div class='bg-primary/5 rounded-xl p-3 mb-3 flex justify-between items-center'>          <div>            <div class='text-xs text-muted'>Producto seleccionado</div>            <div class='font-bold text-sm'>{selProd.nombre}</div>          </div>          <button class='text-xs text-primary font-bold' onclick={() => { form.productoId = ''; form.varianteId = ''; busqProd = ''; }}>Cambiar</button>        </div>        <div class='mb-2'>          <div class='text-xs font-extrabold text-muted mb-2'>Selecciona variante:</div>          {#each variantesDeProducto(form.productoId) as v}            {@const s = stockVariante(lotes, v.id)}            {@const activa = form.varianteId === v.id}            <button class='w-full flex justify-between items-center px-3 py-2.5 text-left border rounded-[var(--radius-md)] mb-1.5 text-sm cursor-pointer transition-colors {activa ? 'bg-primary/10 border-primary' : 'border-border/50 hover:bg-background'}' onclick={() => (form.varianteId = v.id)}>              <span class='font-medium'>{v.nombre} {#if v.esCaja}<span class='text-primary text-xs'>(Caja x{v.unidadesPorCaja})</span>{/if}</span>              <span class='text-xs text-muted'>Stock: {fmtCant(s)} {v.unidad || ''}</span>            </button>          {/each}        </div>      {/if}    {/if}    {#if form.varianteId}      <div class='grid grid-cols-2 gap-2 mb-2'>        <input class='w-full px-3.5 py-3 border border-border rounded-[var(--radius-md)] bg-card text-text text-base outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)]' type='number' inputmode='decimal' step='0.001' placeholder='- merma / + sobrante' bind:value={form.cantidad} />        <select class='w-full px-3.5 py-3 border border-border rounded-[var(--radius-md)] bg-card text-text text-base outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)]' bind:value={form.motivo}>          <option value=''>Motivo...</option>          <option value='merma'>Merma / Dano</option>          <option value='vencimiento'>Vencimiento</option>          <option value='robo'>Robo / Perdida</option>          <option value='error'>Error de registro</option>          <option value='sobrante'>Sobrante en conteo</option>        </select>      </div>      {#if n(form.cantidad) > 0}        <input class='w-full px-3.5 py-3 border border-border rounded-[var(--radius-md)] bg-card text-text text-base outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)] mb-2' type='number' inputmode='decimal' step='0.01' placeholder='Costo unit. del sobrante' bind:value={form.costoSobrante} />      {/if}      <button class='w-full py-3 rounded-[var(--radius-md)] bg-warning text-white font-extrabold text-sm active:scale-[0.97] transition-transform disabled:opacity-50' onclick={registrarAjuste} disabled={procesando}>        <Icono nombre='package' size={16} color='#fff' />        {procesando ? 'Procesando...' : 'Registrar Ajuste'}      </button>    {/if}  </div>  <!-- Inventario por variante --><div class='bg-card rounded-[var(--radius-lg)] p-3 shadow-[var(--color-shadow)] mb-3'>    <div class='flex items-center gap-2 font-extrabold text-primary mb-3 px-1 pt-1'>      <Icono nombre='package' size={18} />      Inventario por variante    </div>    {#if variantes.length === 0}      <div class='text-center text-muted py-6 text-sm'>Sin inventario</div>    {:else}      {#each productos.filter(p => !p.archivado) as p}        {@const vars = variantesDeProducto(p.id)}        {#if vars.length > 0}          <div class='bg-card rounded-[var(--radius-lg)] shadow-[var(--color-shadow)] mb-2 overflow-hidden border border-border/30'>            <button class='w-full flex justify-between items-center px-4 py-3 cursor-pointer gap-2 bg-transparent border-none text-left' onclick={() => (expandido[p.id] = !expandido[p.id])}>              <div class='min-w-0 flex-1'>                <div class='font-extrabold text-primary text-sm'>{p.nombre}</div>                <div class='text-xs text-muted'>{vars.length} variantes</div>              </div>              <Icono nombre='chevron' size={16} class={expandido[p.id] ? 'rotate-180' : ''} />            </button>            {#if expandido[p.id]}              <div class='bg-background px-3 py-2'>                {#each vars as v}                  {@const s = stockVariante(lotes, v.id)}                  {@const val = valorLotesVariante(lotes, v.id)}                  {@const lotesV = lotesDeVariante(lotes, v.id)}                  <div class='mb-2'>                    <div class='flex justify-between items-center py-2 px-3 bg-card rounded-lg border border-border/20'>                      <div>                        <span class='font-bold text-sm'>{v.nombre}</span>                        {#if v.esCaja}                          {@const dec = ConversionService.descomponerStock(s, v.unidadesPorCaja)}                          <span class='text-xs text-primary ml-1'>({dec.cajas} cajas + {fmtCant(dec.unidades)} unidades)</span>                        {/if}                        <div class='text-xs text-muted mt-0.5'>Stock: <b class='text-text'>{fmtCant(s)} {v.unidad || ''}</b> · Valor: <b class='text-primary'>{fmt(val)}</b></div>                      </div>                    </div>                    {#if lotesV.length > 0}                      <div class='pl-4 mt-1 space-y-1'>                        {#each lotesV as l}                          {@const restante = n(l.cantidadInicial) - n(l.cantidadVendida)}                          {@const pct = n(l.cantidadInicial) > 0 ? (restante / n(l.cantidadInicial)) * 100 : 0}                          <div class='flex justify-between items-center text-xs py-2 px-2 bg-card/50 rounded'>                            <div class='flex-1 min-w-0'>                              <div class='flex items-center gap-2'>                                <span>{fmtFH(l.fecha)}</span>                                <div class='w-16 h-1.5 bg-border rounded-full overflow-hidden flex-shrink-0'>                                  <div class='h-full rounded-full {pct > 50 ? 'bg-success' : pct > 20 ? 'bg-warning' : 'bg-danger'}' style='width: {pct}%'></div>                                </div>                              </div>                            </div>                            <div class='text-right flex-shrink-0'>                              <span>{fmtCant(restante)}/{fmtCant(l.cantidadInicial)} {v.unidad || ''}</span>                              <span class='text-muted ml-1'>@{fmt(l.costo)}</span>                            </div>                          </div>                        {/each}                      </div>                    {/if}                  </div>                {/each}              </div>            {/if}          </div>        {/if}      {/each}    {/if}  </div>  <!-- Ultimos ajustes --><div class='bg-card rounded-[var(--radius-lg)] p-4 shadow-[var(--color-shadow)]'>    <div class='flex items-center gap-2 font-extrabold text-primary mb-3'>      <Icono nombre='history' size={18} />      Ultimos ajustes    </div>    {#if ajustesRecientes.length === 0}      <div class='text-center text-muted py-6 text-sm'>Sin ajustes</div>    {:else}      {#each ajustesRecientes as a}        <div class='flex justify-between items-center gap-2 py-3 border-b border-border {esCerrado(a.fecha) ? 'opacity-60' : ''}'>          <div class='min-w-0 flex-1'>            <div class='flex items-center gap-2'>              <div class='w-2 h-2 rounded-full {a.cantidad < 0 ? 'bg-danger' : 'bg-success'}'></div>              <span class='font-bold text-sm'>{a.productoNombre}</span>            </div>            <div class='text-xs text-muted ml-4'>{fmtFH(a.fecha)} · {a.motivo}</div>          </div>          <div class='text-right flex-shrink-0'>            {#if esCerrado(a.fecha)}              <span class='inline-block px-2 py-0.5 rounded-full text-[0.6rem] font-extrabold text-white bg-warning'>CERRADO</span>            {:else}              <div class='font-extrabold {a.cantidad < 0 ? 'text-danger' : 'text-success'}'>{a.cantidad > 0 ? '+' : ''}{fmtCant(a.cantidad)}</div>              {#if a.costoPerdida}<div class='text-xs text-danger'>-{fmt(a.costoPerdida)}</div>{/if}            {/if}          </div>        </div>      {/each}    {/if}  </div></div>